// Writes src/codec/files.ts: every generated file descriptor, so the registry
// that resolves Any type URLs and event types knows each message the chain
// can emit. Runs after buf generate; gen:check diffs the result.
import { readdirSync, statSync, readFileSync, writeFileSync } from "node:fs";
import { join, relative, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const gen = join(root, "src", "gen");
const out = join(root, "src", "codec", "files.ts");

function walk(dir, files) {
  for (const entry of readdirSync(dir).sort()) {
    const path = join(dir, entry);
    if (statSync(path).isDirectory()) walk(path, files);
    else if (path.endsWith("_pb.ts")) files.push(path);
  }
  return files;
}

const entries = [];
for (const path of walk(gen, [])) {
  const match = readFileSync(path, "utf8").match(/^export const (file_\w+): GenFile/m);
  if (!match) continue;
  const spec = "../gen/" + relative(gen, path).replace(/\.ts$/, ".js");
  entries.push({ name: match[1], spec });
}

let src = "// Generated by scripts/gen-files.mjs from src/gen; do not edit.\n";
src += 'import type { GenFile } from "@bufbuild/protobuf/codegenv2";\n';
for (const { name, spec } of entries) src += `import { ${name} } from "${spec}";\n`;
src += "\n/** Every generated file descriptor, in path order. */\nexport const generatedFiles: readonly GenFile[] = [\n";
for (const { name } of entries) src += `  ${name},\n`;
src += "];\n";
writeFileSync(out, src);
console.log(`${relative(root, out)}: ${entries.length} files`);
